                    <span class=\"service__main_title\"><?= $service[\"NAME\"] ?></span>\n                                </div>\n                                <div class=\"service__text\">\n                                    <? if ($service[\"PREVIEW_TEXT\"]) { ?>\n                                        <?= substr($service[\"PREVIEW_TEXT\"], 0, 130) ?>...\n                                    <? } ?>\n                                </div>\n                            </div>\n                            <div class=\"service__img img\">\n                                <img class=\"img_inner img_inner--all_width\"\n                                    src=\"<?= $service[\"DETAIL_PICTURE\"]; ?>\" alt=\"\">\n                            </div>\n                        </a>\n                    <? endforeach; ?>\n                </div>\n            </div>\n        </div>\n    </section>\n<? endif; ?>\n\n<script type=\"text/javascript\">\n    var <? echo $strObName; ?> =\n    new JCCatalogElement(<? echo CUtil::PhpToJSObject($arJSParams, false, true); ?>);\n    BX.message({\n        ECONOMY_INFO_MESSAGE: '<? echo GetMessageJS('CT_BCE_CATALOG_ECONOMY_INFO'); ?>',\n        BASIS_PRICE_MESSAGE: '<? echo GetMessageJS('CT_BCE_CATALOG_MESS_BASIS_PRICE') ?>',\n        TITLE_ERROR: '<? echo GetMessageJS('CT_BCE_CATALOG_TITLE_ERROR') ?>',\n        TITLE_BASKET_PROPS: '<? echo GetMessageJS('CT_BCE_CATALOG_TITLE_BASKET_PROPS') ?>',\n        BASKET_UNKNOWN_ERROR: '<? echo GetMessageJS('CT_BCE_CATALOG_BASKET_UNKNOWN_ERROR') ?>',\n        BTN_SEND_PROPS: '<? echo GetMessageJS('CT_BCE_CATALOG_BTN_SEND_PROPS'); ?>',\n        BTN_MESSAGE_BASKET_REDIRECT: '<? echo GetMessageJS('CT_BCE_CATALOG_BTN_MESSAGE_BASKET_REDIRECT') ?>',\n        BTN_MESSAGE_CLOSE: '<? echo GetMessageJS('CT_BCE_CATALOG_BTN_MESSAGE_CLOSE'); ?>',\n        BTN_MESSAGE_CLOSE_POPUP: '<? echo GetMessageJS('CT_BCE_CATALOG_BTN_MESSAGE_CLOSE_POPUP'); ?>',\n        TITLE_SUCCESSFUL: '<? echo GetMessageJS('CT_BCE_CATALOG_ADD